  if (!sokalBarracksHeld) await run('document.querySelector("#presentation").click()');
  assert.equal(await run('Boolean(document.querySelector("#street-toggle"))'), false);
  function waitForExplorationViewport() {
    const source = JSON.stringify(`data:image/png;base64,${frame.enhancedFrame}`);
    return waitFor("the default WebGL exploration viewport", () => run(`state.sequence === ${frame.sequence} &&
      document.querySelector("#screen").src === ${source} &&
      document.querySelector("#tile-art:not([hidden]) .street-viewport")?.isConnected`));
  }
  async function verifySceneryPrompt(position, expectedCaption, record = false) {
    assert.equal(frame.portrait, undefined);
    assert.equal(frame.classicPortrait, false);
    assert.equal(frame.encounter, undefined);
    assert.deepEqual([frame.scenery?.area, frame.scenery?.x, frame.scenery?.y], position);
    await waitForExplorationViewport();
    assert.equal(await run('Boolean(document.querySelector("#tile-art:not([hidden]) .encounter-portrait, #tile-art:not([hidden]) .encounter-sprite"))'), false);
    const caption = frame.text.toSorted(([left], [right]) => left - right)
      .map(([, character]) => String.fromCharCode(character)).join("");
    if (expectedCaption) assert.match(caption, expectedCaption);
    if (record && heldPortraitEvidenceFile) {
      const renderer = await fetch(new URL("/play.js", origin));
      assert.ok(renderer.ok);
      heldPortraitEvidence.push({
        route: routeName, data: frame.classicAvailable === false ? "port" : "original", position, caption,
        checkpointSha256: createHash("sha256").update(readFileSync(checkpoint)).digest("hex"),
        rendererSha256: createHash("sha256").update((await renderer.text()).replace(/\r\n/g, "\n")).digest("hex"),
      });
    }
  }
  function patrolApproachPlacement(area) {
    return [56, 32, `encounter:area:${area}:SPRIT5.DAX:16:2:0`, 16, 49];
  }
  async function verifyHeldApproach(expectedCaption, expectedPosition, placement) {
    const [, , actor, width, height] = placement;
    const caption = frame.text.toSorted(([a], [b]) => a - b).map(([, ch]) => String.fromCharCode(ch)).join("");
    assert.match(caption, expectedCaption);
    assert.ok(frame.awaitsKey);
    assert.equal(frame.portrait, undefined);
    assert.deepEqual(frame.encounter, placement);
    const location = frame.scenery ?? frame.exploration;
    const position = [location?.mapId ?? location?.area, location?.x, location?.y];
    assert.deepEqual(position, expectedPosition);
    await waitFor("the held encounter sprite at its approach anchor", () => run(`
      state.sequence === ${frame.sequence} && !animationFrame && !renderingSequence &&
      window.observedApproach.has(${JSON.stringify(actor)})`));
    const { result, exceptionDetails } = await command("Runtime.evaluate", {
      awaitPromise: true, returnByValue: true,
      expression: `new Promise(resolve => {
        const start = performance.now();
        function sample(now) {
          const layer = document.querySelector('#tile-art:not([hidden])');
          const actor = layer?.querySelector('.encounter-sprite');
          if (state.sequence !== ${frame.sequence} || animationFrame || !actor?.complete ||
              actor.getAttribute('src') !== ${JSON.stringify("/art/" + actor)} ||
              actor.naturalWidth !== ${width * 4} || actor.naturalHeight !== ${height * 4} ||
              !actor.getBoundingClientRect().width || layer.querySelector('.encounter-portrait')) return resolve(false);
          if (now - start >= 2100) return resolve(true);
          requestAnimationFrame(sample);
        }
        requestAnimationFrame(sample);
      })`,
    });
    assert.ok(!exceptionDetails && result.value, "The far approach must hold through the prompt");
    if (illustration?.heldApproachCapture) {
      const shot = await command("Page.captureScreenshot", { format: "png" });
      writeFileSync(resolve(directory, illustration.heldApproachCapture), Buffer.from(shot.data, "base64"));
    }
    if (illustration?.heldApproachRoofed) {
      const overhead = await run(`(() => {
        const canvas = document.querySelector("#tile-art:not([hidden]) canvas.street-viewport");
        if (!canvas) return null;
        const gl = canvas.getContext("webgl");
        const pixel = new Uint8Array(4);
        gl.readPixels(Math.floor(canvas.width / 2), Math.floor(canvas.height * .94), 1, 1,
          gl.RGBA, gl.UNSIGNED_BYTE, pixel);
        return [...pixel];
      })()`);
      assert.ok(overhead && overhead[3] === 255 && Math.max(...overhead.slice(0, 3)) < 48,
        `Expected the lit WebGL viewport to show dark cave overhead, got ${JSON.stringify(overhead)}`);
      assert.equal(frame.scenery?.roofed, true);
    }
    const [renderer, art] = await Promise.all([fetch(origin + "/play.js"), fetch(origin + "/art/" + actor)]);
    assert.ok(renderer.ok && art.ok);
    heldPortraitEvidence.push({
      route: routeName, data: frame.classicAvailable === false ? "port" : "original", position, caption,
      checkpointSha256: createHash("sha256").update(readFileSync(checkpoint)).digest("hex"),
      rendererSha256: createHash("sha256").update((await renderer.text()).replace(/\r\n/g, "\n")).digest("hex"),
      encounter: { placement, sha256: createHash("sha256").update(Buffer.from(await art.arrayBuffer())).digest("hex") },
    });
  }
  function observeApproach(approachSequence, requireScenery = true, requireWebGL = false, timed = false) {
    return run(`(() => {
      window.observedApproach = new Set();
      const layer = document.querySelector("#tile-art");
      function recordApproach() {
        const img = layer.querySelector(".encounter-sprite");
        const scenerySelector = ${JSON.stringify(requireWebGL ? ".street-viewport" : ".street-viewport, .perspective-backdrop")};
        if (!img || ((${requireScenery} || ${requireWebGL}) && !layer.querySelector(scenerySelector))) return;
        if (${timed} && (layer.hidden || !animationFrame?.encounter || !img.complete || !img.getClientRects().length)) return;
        const view = animationFrame ?? state;
        const projected = view.perspective && !view.portrait;
        for (const [x, y, id, w, h, webglYOffset = 0] of ${JSON.stringify(approachSequence)}) {
          if (${timed} && view.encounter[2] !== id) continue;
          const left = (projected ? 8 + (x - 24) * 120 / 88 : x) / 3.2;
          const top = (projected ? 8 + (y + webglYOffset - 24) * 120 / 88 : y) / 2;
          if (img.getAttribute("src") === "/art/" + id && img.naturalWidth === w * 4 && img.naturalHeight === h * 4 &&
              Math.abs(parseFloat(img.style.left) - left) < .001 && Math.abs(parseFloat(img.style.top) - top) < .001) {
            window.observedApproach.add(id);
          }
        }
      }
      new MutationObserver(recordApproach).observe(layer, { childList: true });
      layer.addEventListener("load", recordApproach, true);
      if (${timed}) {
        const announced = window.announcedApproaches = new Set();
        function sampleApproach() {
          for (const clip of [animationFrame, ...animationQueue]) {
            if (clip?.encounter) announced.add(clip.encounter[2]);
          }
          recordApproach();
          if (window.observedApproach.size < ${approachSequence.length}) requestAnimationFrame(sampleApproach);
        }
        requestAnimationFrame(sampleApproach);
      }
    })()`);
  }

  async function verifyTiledView(area, patterns) {
    if (!frame.tileInventory?.length) return 0;
    if (environmentTrace) appendFileSync(environmentTrace, JSON.stringify(frame.tileInventory) + "\n");
    const expected = frame.tileInventory.map(([x, y, id]) => [x, y, id]);
    assert.equal(expected.length, 121);
    if (frame.tiles.length < expected.length) {
      const placed = new Set(frame.tiles.map(([x, y, id]) => `${x},${y},${id}`));
      const missing = expected.filter(([x, y, id]) => !placed.has(`${x},${y},${id}`));
      assert.fail(`Missing ${missing.length} tile placements in ${routeName}: ${missing.map(([x, y, id]) => `(${x},${y}) ${id}`).join(", ")}`);
    }
    assert.deepEqual(frame.tiles, expected);
    for (const [, , id] of expected) {
      assert.ok(id.startsWith(`tile:${area}:`), id);
      patterns.add(id);
    }
    assert.ok(frame.perspective && (frame.scenery || frame.exploration?.area === 0),
      `Missing WebGL camera data in ${routeName}`);
    await waitForExplorationViewport();
    return 1;
  }

